type LinkChainValue struct {
	// LinkChain The inline link chain definition.
	//
	// Examples: [{"link_0_capsule":{"shape":{"cylinder_height":20,"radius":5,"shape_type":"capsule"}},"link_0_sphere":{"pose":{"position":[0,0,-10]},"shape":{"radius":10,"shape_type":"sphere"}}},{},{"link_2_capsule":{"shape":{"cylinder_height":20,"radius":5,"shape_type":"capsule"}}}]
	LinkChain LinkChain `json:"link_chain"`

	// Source Discriminator value indicating an inline value.
	Source LinkChainValueSource `json:"source"`
}

// LinkChainValueSource Discriminator value indicating an inline value.
type LinkChainValueSource string

